e of the Trails', NULL, NULL, NULL, 'EN', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.3390/su15107741', NULL, NULL, NULL, NULL, 'https://doi.org/10.3390/su15107741', '2026-09-18', NULL, NULL, 3, 'clinical', 'HR', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 04:20', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:21', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'crossref-api', NULL, 1, NULL, '7741', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'lower_control', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
