INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (65, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', NULL, 'disabled people''s organisation wheelchair user first-person account ramp gradient too steep independent access', NULL, 'consensus', 'systematic', 'none', 10, 10, 1, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:21', 'PRIOR FALSIFIED ON THE ONE CLAUSE THAT MATTERED. I predicted testimonial-not-dimensional; the top hit is DIMENSIONAL AND CO-PRODUCED. REF-01001 (Lepoglavec 2023, Sustainability) derives 5.50% as the tipping point after which all eight wheelchair-using subjects experienced uncertainty, and >9.01% as almost impassable on gravel, from instrumented field measurement -- GNSS and geodetic station, heart-rate telemetry -- and states that people with disabilities were included in the implementation of the research through the Croatian Association of Paraplegics and Tetraplegics (HUPT), a NAMED organisation. THE Co-1 QUESTION IS THEREFORE LIVE AND DECISIVE, and it is raised as GAP-010 rather than answered here: ''included in the implementation'' does not separate co-production from participation-as-subjects (D-0178), MDPI is Akamai-blocked, and admitting Co-1 on an ambiguous sentence is the mirror of the failure CLAUDE.md section 6 forbids. Admitted at the ladder-derived T3 (clinical + lower_control) in the meantime. ALSO SURFACED, staged not admitted: Pettersson 2022, a thematic analysis of 88 discrimination complaints filed with the Swedish Equality Ombudsman by wheeled-mobility-device users -- first-person accounts routed through a national equality body, which is a Co-1-adjacent shape this corpus has no instance of. Overlap with REF-00977/00999/01000 confirms partial saturation on the qualitative seam opened at exec 64.', 0, 'The Co-1 seam for ramps has been worked hard -- batch 09 admitted REF-00989 and REF-00993, batches 13-14 found the professional-body route empty -- so expect LOW yield and high overlap, and expect any new material to be testimonial rather than dimensional. Expect 0-1 admissions. FALSIFIED IF a disabled people''s organisation states or contests a gradient figure, which would be a Co-1 value meeting spec 7''s falsification condition from the co-primary side.');

