scripts/migrations/data_20260827194239_2026-08-27-rename-execution.sql:21:INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0174', 'D-METH', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'Relevance is an adjudication made at evidence collection, against a topic; applicability remains a synthesis judgement.', 'ADOPTED by owner ruling 2026-08-27: "evidence states relevant items, and relevancy is something that must be adjudicated against a topic/category/concept."', 'Relevance is not a property a document carries but a relation, so evidence collection judges -- it simply judges a different question from judgment. This refutes an agent finding that the evidence stage was a "pure log" and that R1 (phase before-admitting) therefore conflicted with it; there is no conflict. The distinction from applicability must be protected: DR-2026-08-24 §2.4 defers applicability and says nothing about relevance, and cannot, since relevance must be settled at collection or nothing can be admitted. Conflating them breaks both ways. Measured defect: source_slug_links.relevance_note exists and is populated in 0 of 10 rows, and search_admissions records no grounds at all -- the adjudication is made every time and recorded never. Under the harvest ruling (D-0173) the grounds become derivable rather than hand-written.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-relevance-is-adjudicated-at-collection.md", "references/project-standards.md (entries dated 2026-08-27)"]', '["Treat evidence collection as a pure log with all judgement deferred -- refuted by the owner: \"relevant\" is itself an adjudication."]', 'Granularity gap measured: the owner names topic/category/concept, but slugs is flat -- no parent, category, group or level column, 106 leaves. A source relevant at the category level can only be copied across every leaf (rule 5) or lost. The owner has ruled parent columns are needed.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
